package lk.sliit.nutricare.health;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")public class HealthController{private final HealthCheckRepository checks;private final HealthAlertRepository alerts;HealthController(HealthCheckRepository c,HealthAlertRepository a){checks=c;alerts=a;}@PostMapping("/checkups")@PreAuthorize("hasAnyRole('DOCTOR','MEDICAL_CENTER_COORDINATOR')")@ResponseStatus(HttpStatus.CREATED)@Transactional public Result create(@Valid@RequestBody CheckRequest r){HealthCheck c=checks.save(new HealthCheck(r.patientId(),r.practitionerId(),r.weightKg(),r.bmi(),r.systolic(),r.diastolic(),r.bloodSugar(),r.temperature(),r.notes()));List<HealthAlert>made=new ArrayList<>();if(r.bloodSugar()!=null&&r.bloodSugar().compareTo(new BigDecimal("140"))>0)made.add(alerts.save(new HealthAlert(c.getId(),r.patientId(),"HIGH","Blood sugar exceeds the demo threshold of 140 mg/dL")));if(r.systolic()!=null&&r.systolic()>140)made.add(alerts.save(new HealthAlert(c.getId(),r.patientId(),"MEDIUM","Blood pressure exceeds the demo threshold")));return new Result(c,made,"Thresholds are demonstration values and are not diagnostic.");}@GetMapping("/checkups/patient/{id}")@PreAuthorize("hasAnyRole('DIETITIAN','DOCTOR','MEDICAL_CENTER_COORDINATOR') or principal == #id")List<HealthCheck>history(@PathVariable UUID id){return checks.findByPatientIdOrderByRecordedAtDesc(id);}@GetMapping("/health-alerts")@PreAuthorize("hasAnyRole('DIETITIAN','DOCTOR','MEDICAL_CENTER_COORDINATOR')")List<HealthAlert>alerts(){return alerts.findByStatusOrderByCreatedAtDesc("OPEN");}record CheckRequest(@NotNull UUID patientId,@NotNull UUID practitionerId,@Positive BigDecimal weightKg,@Positive BigDecimal bmi,@Positive Integer systolic,@Positive Integer diastolic,@Positive BigDecimal bloodSugar,@Positive BigDecimal temperature,String notes){}record Result(HealthCheck check,List<HealthAlert>alerts,String disclaimer){}
}
